<script>
(()=>{const product=<?= json_encode($product, JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT) ?>,key='tmp-store-cart-<?= e($store['uid']) ?>',wishKey='tmp-store-wishlist-<?= e($store['uid']) ?>',recentKey='tmp-store-recent-<?= e($store['uid']) ?>';let cart={},wishlist=[],recent=[];try{cart=JSON.parse(localStorage.getItem(key)||'{}')||{}}catch(e){}try{wishlist=JSON.parse(localStorage.getItem(wishKey)||'[]')||[]}catch(e){}try{recent=JSON.parse(localStorage.getItem(recentKey)||'[]')||[]}catch(e){}recent=[String(product.uid),...recent.filter(uid=>uid!==String(product.uid))].slice(0,12);localStorage.setItem(recentKey,JSON.stringify(recent));const favorite=document.querySelector('[data-favorite]'),lightbox=document.querySelector('[data-lightbox]'),main=document.querySelector('[data-main-image]');const updateCount=()=>document.querySelector('[data-cart-count]').textContent=Object.values(cart).reduce((sum,item)=>sum+Number(item.quantity||0),0);const updateFavorite=()=>{const active=wishlist.includes(String(product.uid));favorite?.classList.toggle('active',active);if(favorite)favorite.textContent=active?'♥ Guardado':'♡ Guardar'};document.querySelectorAll('[data-image]').forEach(button=>button.onclick=()=>{main.src=button.dataset.image;document.querySelectorAll('[data-image]').forEach(item=>item.classList.toggle('active',item===button))});document.querySelector('[data-add-product]')?.addEventListener('click',event=>{const quantity=Math.max(1,Math.min(99,Number(document.querySelector('[data-quantity]').value)||1)),current=cart[product.uid]||{product,quantity:0};current.product=product;current.quantity=Number(current.quantity||0)+quantity;cart[product.uid]=current;localStorage.setItem(key,JSON.stringify(cart));updateCount();event.currentTarget.textContent='Agregado ✓';setTimeout(()=>event.currentTarget.textContent='Agregar al carrito',1100)});favorite?.addEventListener('click',()=>{wishlist=wishlist.includes(String(product.uid))?wishlist.filter(uid=>uid!==String(product.uid)):[...wishlist,String(product.uid)];localStorage.setItem(wishKey,JSON.stringify(wishlist));updateFavorite()});document.querySelector('[data-share]')?.addEventListener('click',async event=>{try{if(navigator.share)await navigator.share({title:product.name,url:location.href});else{await navigator.clipboard.writeText(location.href);event.currentTarget.textContent='✓ Enlace copiado';setTimeout(()=>event.currentTarget.textContent='↗ Compartir',1200)}}catch(e){}});document.querySelector('[data-zoom]')?.addEventListener('click',()=>{if(!main)return;document.querySelector('[data-lightbox-image]').src=main.src;lightbox.classList.add('open');lightbox.setAttribute('aria-hidden','false');document.body.style.overflow='hidden'});const close=()=>{lightbox.classList.remove('open');lightbox.setAttribute('aria-hidden','true');document.body.style.overflow=''};document.querySelector('[data-lightbox-close]').onclick=close;lightbox.addEventListener('click',event=>{if(event.target===lightbox)close()});document.addEventListener('keydown',event=>{if(event.key==='Escape')close()});updateFavorite();updateCount()})();
